import type {
  AppetiteResult,
  ConstructionClass,
  LineOfBusiness,
  RecommendedAction,
  RiskBand,
  RiskSignal,
  SubmissionStatus,
} from '../graphql/schema-types.generated';

/** Shapes of `seed-data.json` (generated by scripts/generate-seed.mjs). */
export interface SeedExtractedField {
  key: string;
  label: string;
  value: string;
}

export interface SeedDocument {
  id: string;
  fileName: string;
  type: string;
  sizeBytes: number;
  pageCount: number;
  uploadedAt: string;
  extractedFields: SeedExtractedField[];
}

export interface SeedLoss {
  id: string;
  lossDate: string;
  cause: string;
  description: string;
  amountPaid: number;
  amountReserved: number;
  status: 'OPEN' | 'CLOSED';
}

export interface SeedSubmission {
  id: string;
  reference: string;
  status: SubmissionStatus;
  lineOfBusiness: LineOfBusiness;
  premium: number;
  receivedAt: string;
  decidedAt: string | null;
  applicant: {
    name: string;
    industry: string;
    yearsInBusiness: number;
    annualRevenue: number;
    street: string;
    city: string;
    state: string;
    zip: string;
  };
  broker: { name: string; agency: string; email: string };
  property: {
    constructionClass: ConstructionClass;
    occupancy: string;
    yearBuilt: number;
    stories: number;
    squareFeet: number;
    sprinklered: boolean;
    protectionClass: number;
    tiv: number;
    floodZone: string;
    distanceToCoastMiles: number;
    roofAgeYears: number | null;
    openRecommendations: number | null;
  };
  losses: SeedLoss[];
  documents: SeedDocument[];
  historicalDecision: {
    id: string;
    finalAction: RecommendedAction;
    underwriter: string;
    decidedAt: string;
    reason: string;
  } | null;
}

/** REST shape of an appetite rule (mirrors the backend entity JSON). */
export interface AppetiteRuleDto {
  id: number;
  name: string;
  lineOfBusiness: LineOfBusiness;
  state: string | null;
  constructionClass: ConstructionClass | null;
  maxTiv: number;
  active: boolean;
  notes: string;
}

export interface SeedData {
  generatedAt: string;
  submissions: SeedSubmission[];
  appetiteRules: AppetiteRuleDto[];
}

export interface AppetiteEvaluation {
  result: Omit<AppetiteResult, '__typename'>;
  tivExcessRatio: number | null;
}

export type Signal = Omit<RiskSignal, '__typename' | 'citation'> & {
  citation: { documentId: string | null; documentName: string; field: string; value: string };
};

export interface AssessmentDraft {
  provider: string;
  model: string | null;
  riskScore: number;
  riskBand: RiskBand;
  confidence: number;
  summary: string;
  signals: Signal[];
  recommendedAction: RecommendedAction;
  rationale: string;
}
